-- public.ramp_refusal(p_la integer, p_lb integer, p_apart double precision, p_n integer)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.ramp_refusal(p_la integer, p_lb integer, p_apart double precision, p_n integer)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select 'Ends ' || metres(p_apart) || ' m apart in height'
      || case when p_la <> p_lb
              then ' (' || case when p_la = 0 then 'the ground' else 'storey ' || (p_la + 1) end
                || ' to ' || case when p_lb = 0 then 'the ground' else 'storey ' || (p_lb + 1) end || ')'
              else '' end
      || '. Max rise ' || metres(ramp_slope())
      || ' m/tile: needs ' || ceil(p_apart / ramp_slope())::int || ' tiles of deck; has ' || p_n || '.'
$function$
